import{_ as n,o as i,c as s,a2 as e}from"./chunks/framework.CqpfiAoK.js";const o=JSON.parse('{"title":"Klasifikasi dan Simbiosis Ras Asing","description":"","frontmatter":{},"headers":[],"relativePath":"id/52-异族分类与共生.md","filePath":"id/52-异族分类与共生.md","lastUpdated":1789183869000}'),r={name:"id/52-异族分类与共生.md"};function t(d,a,u,k,g,l){return i(),s("div",null,[...a[0]||(a[0]=[e('<h1 id="klasifikasi-dan-simbiosis-ras-asing" tabindex="-1">Klasifikasi dan Simbiosis Ras Asing <a class="header-anchor" href="#klasifikasi-dan-simbiosis-ras-asing" aria-label="Permalink to &quot;Klasifikasi dan Simbiosis Ras Asing&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>52</td></tr><tr><td>Modul</td><td>Ras dan Bentuk Kehidupan</td></tr><tr><td>Kata Kunci Inti</td><td>Ras asing, kriteria klasifikasi, mode simbiosis, penghormatan budaya, adaptasi ras</td></tr></tbody></table><h2 id="i-definisi-konsep-ras-asing" tabindex="-1">I. Definisi Konsep Ras Asing <a class="header-anchor" href="#i-definisi-konsep-ras-asing" aria-label="Permalink to &quot;I. Definisi Konsep Ras Asing&quot;">​</a></h2><p>Dalam konteks Peradaban Simbiosis Jangkar, &quot;ras asing&quot; adalah konsep yang relatif terhadap Ras Manusia, merujuk pada semua ras di luar Ras Manusia. Perlu ditekankan secara khusus bahwa konsep &quot;ras asing&quot; hanya memiliki makna taksonomi, dan tidak membawa penilaian nilai atau makna diskriminatif apa pun. Dalam kerangka Konstitusi Simbiosis, ras asing dan Ras Manusia menikmati status hukum dan hak dasar yang sepenuhnya setara.</p><p>Tujuan diperkenalkannya konsep ras asing adalah untuk memahami dan mempelajari secara sistematis berbagai bentuk kehidupan di luar Ras Manusia, memberikan dasar ilmiah untuk merumuskan kebijakan simbiosis yang ditargetkan, langkah-langkah perlindungan budaya, dan rencana adaptasi ras, bukan untuk memperlakukan ras asing sebagai &quot;yang lain&quot; atau &quot;yang aneh&quot;.</p><h2 id="ii-kriteria-klasifikasi-ras-asing" tabindex="-1">II. Kriteria Klasifikasi Ras Asing <a class="header-anchor" href="#ii-kriteria-klasifikasi-ras-asing" aria-label="Permalink to &quot;II. Kriteria Klasifikasi Ras Asing&quot;">​</a></h2><p>Ras asing di Hengyuanzhou diklasifikasikan menurut berbagai dimensi, membentuk sistem klasifikasi multidimensi:</p><h3 id="a-berdasarkan-garis-keturunan-kehidupan" tabindex="-1">(A) Berdasarkan Garis Keturunan Kehidupan <a class="header-anchor" href="#a-berdasarkan-garis-keturunan-kehidupan" aria-label="Permalink to &quot;(A) Berdasarkan Garis Keturunan Kehidupan&quot;">​</a></h3><p>Ini adalah kriteria klasifikasi paling dasar, lihat 《50-Tinjauan Silsilah Semua Ras》:</p><table tabindex="0"><thead><tr><th>Garis Keturunan</th><th>Ras Asing yang Termasuk</th></tr></thead><tbody><tr><td>Ras Materi Berbasis Karbon</td><td>Ras Hewan, Ras Bersisik, Ras Bersayap, Ras Pohon, dll.</td></tr><tr><td>Ras Energi Terkondensasi</td><td>Ras Roh, Ras Api, Ras Air, Ras Angin, Ras Petir, dll.</td></tr><tr><td>Ras Konstruksi Mekanis</td><td>Ras Mesin, Ras Angka, Ras Kristal, dll.</td></tr><tr><td>Ras Informasi Kesadaran</td><td>Ras Mimpi, Ras Bayangan, Ras Pikiran, Ras Jiwa, dll.</td></tr><tr><td>Ras Mutasi Campuran</td><td>Ras Semi-hewan, Ras Roh Iblis, Ras Manusia-Mesin, Tubuh Jiwa Ganda, dll.</td></tr></tbody></table><h3 id="b-berdasarkan-tingkat-peradaban" tabindex="-1">(B) Berdasarkan Tingkat Peradaban <a class="header-anchor" href="#b-berdasarkan-tingkat-peradaban" aria-label="Permalink to &quot;(B) Berdasarkan Tingkat Peradaban&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tingkat</th><th>Nama</th><th>Karakteristik</th><th>Ras Representatif</th></tr></thead><tbody><tr><td>Tingkat Pertama</td><td>Ras Peradaban Primitif</td><td>Belum membangun sistem sosial yang stabil, bertahan hidup dalam bentuk suku</td><td>Beberapa cabang Ras Hewan, Ras Pohon Primitif</td></tr><tr><td>Tingkat Kedua</td><td>Ras Peradaban Klasik</td><td>Telah membangun sistem negara dan budaya klasik, berada pada tahap pertanian atau kerajinan tangan</td><td>Beberapa Ras Bersisik, Ras Bersayap</td></tr><tr><td>Tingkat Ketiga</td><td>Ras Peradaban Teknologi</td><td>Telah mengembangkan peradaban teknologi, memasuki era industri atau informasi</td><td>Ras Mesin, Ras Angka, beberapa Ras Manusia</td></tr><tr><td>Tingkat Keempat</td><td>Ras Peradaban Kultivasi</td><td>Menggunakan sistem kultivasi sebagai bentuk peradaban inti, kultivator mendominasi masyarakat</td><td>Ras Roh, Ras Naga, beberapa Ras Manusia</td></tr><tr><td>Tingkat Kelima</td><td>Ras Peradaban Simbiosis</td><td>Telah bergabung dengan Peradaban Simbiosis Jangkar, menerima cita-cita dan institusi simbiosis</td><td>Semua ras yang bergabung dengan peradaban simbiosis</td></tr></tbody></table><h3 id="c-berdasarkan-adaptasi-lingkungan" tabindex="-1">(C) Berdasarkan Adaptasi Lingkungan <a class="header-anchor" href="#c-berdasarkan-adaptasi-lingkungan" aria-label="Permalink to &quot;(C) Berdasarkan Adaptasi Lingkungan&quot;">​</a></h3><ul><li><strong>Ras Terestrial</strong>: Ras yang beradaptasi dengan lingkungan darat, seperti Ras Manusia, Ras Hewan, Ras Mesin.</li><li><strong>Ras Akuatik</strong>: Ras yang beradaptasi dengan lingkungan perairan, seperti Ras Bersisik, Ras Air, beberapa ras campuran.</li><li><strong>Ras Udara</strong>: Ras yang beradaptasi dengan lingkungan ketinggian atau penerbangan, seperti Ras Bersayap, Ras Angin.</li><li><strong>Ras Api</strong>: Ras yang beradaptasi dengan lingkungan suhu tinggi, seperti Ras Api, beberapa Ras Bersisik.</li><li><strong>Ras Es</strong>: Ras yang beradaptasi dengan lingkungan suhu rendah, seperti Ras Es, beberapa Ras Pohon.</li><li><strong>Ras Energi</strong>: Ras yang beradaptasi dengan lingkungan energi konsentrasi tinggi, seperti Ras Roh, Ras Petir.</li><li><strong>Ras Ruang</strong>: Ras yang beradaptasi dengan lingkungan celah ruang atau ruang asing, seperti Ras Bayangan, beberapa Ras Pikiran.</li></ul><h3 id="d-berdasarkan-bentuk-sosial" tabindex="-1">(D) Berdasarkan Bentuk Sosial <a class="header-anchor" href="#d-berdasarkan-bentuk-sosial" aria-label="Permalink to &quot;(D) Berdasarkan Bentuk Sosial&quot;">​</a></h3><ul><li><strong>Ras Individualis</strong>: Menekankan kemandirian dan kebebasan individu, struktur sosial longgar, seperti beberapa Ras Roh, Ras Bayangan.</li><li><strong>Ras Kolektivis</strong>: Menekankan kepentingan dan kerja sama kolektif, struktur sosial erat, seperti Ras Semut, Ras Lebah, beberapa Ras Mesin.</li><li><strong>Ras Familialis</strong>: Menggunakan keluarga darah sebagai unit sosial dasar, seperti Ras Naga, beberapa Ras Hewan.</li><li><strong>Ras Religius</strong>: Menggunakan keyakinan agama sebagai inti kohesi sosial, seperti beberapa ras pengorbanan.</li><li><strong>Ras Teknologi</strong>: Menggunakan pengembangan teknologi sebagai tujuan sosial inti, seperti Ras Mesin, Ras Angka.</li></ul><h2 id="iii-mode-simbiosis-utama-ras-asing" tabindex="-1">III. Mode Simbiosis Utama Ras Asing <a class="header-anchor" href="#iii-mode-simbiosis-utama-ras-asing" aria-label="Permalink to &quot;III. Mode Simbiosis Utama Ras Asing&quot;">​</a></h2><p>Untuk berbagai jenis ras asing, Peradaban Simbiosis Jangkar mengadopsi mode simbiosis yang berbeda:</p><h3 id="a-mode-simbiosis-ras-materi-berbasis-karbon" tabindex="-1">(A) Mode Simbiosis Ras Materi Berbasis Karbon <a class="header-anchor" href="#a-mode-simbiosis-ras-materi-berbasis-karbon" aria-label="Permalink to &quot;(A) Mode Simbiosis Ras Materi Berbasis Karbon&quot;">​</a></h3><ul><li><strong>Ras Hewan</strong>: Memanfaatkan keunggulan kemampuan fisik dan indra Ras Hewan, memainkan peran penting dalam bidang eksplorasi sumber daya, keamanan dan pertahanan, serta pemantauan lingkungan. Pada saat yang sama, melindungi budaya suku dan tradisi liar Ras Hewan, melarang domestikasi paksa.</li><li><strong>Ras Bersisik</strong>: Memanfaatkan kemampuan adaptasi akuatik Ras Bersisik, memainkan peran dalam bidang pengembangan sumber daya perairan, konstruksi bawah air, dan perlindungan ekosistem perairan. Ras Naga, sebagai cabang kuat Ras Bersisik, memainkan peran penting dalam kultivasi tingkat tinggi dan pertahanan peradaban.</li><li><strong>Ras Bersayap</strong>: Memanfaatkan kemampuan terbang Ras Bersayap, memainkan peran dalam bidang transportasi udara, pemantauan cuaca, dan patroli udara. Melindungi habitat ketinggian dan rute migrasi Ras Bersayap.</li><li><strong>Ras Pohon</strong>: Memanfaatkan kemampuan simbiosis alami Ras Pohon, memainkan peran dalam bidang perlindungan ekologis, pengelolaan lingkungan, pengembangan sumber daya tanaman, dan penyembuhan medis. Umur panjang Ras Pohon menjadikannya kekuatan penting untuk pewarisan sejarah dan perencanaan jangka panjang.</li></ul><h3 id="b-mode-simbiosis-ras-energi-terkondensasi" tabindex="-1">(B) Mode Simbiosis Ras Energi Terkondensasi <a class="header-anchor" href="#b-mode-simbiosis-ras-energi-terkondensasi" aria-label="Permalink to &quot;(B) Mode Simbiosis Ras Energi Terkondensasi&quot;">​</a></h3><ul><li><strong>Ras Roh</strong>: Memanfaatkan kemampuan manipulasi energi dan bakat kultivasi Ras Roh, memainkan peran inti dalam bidang penelitian sistem kultivasi, regulasi energi, dan bimbingan kultivasi tingkat tinggi. Ras Roh adalah peneliti dan pewaris penting dari tiga ratus sistem kultivasi asli.</li><li><strong>Ras Elemental (Api/Air/Angin/Petir)</strong>: Memanfaatkan kemampuan manipulasi elemental setiap ras, memainkan peran dalam bidang pengembangan energi, pengelolaan lingkungan, produksi industri, dan pencegahan bencana. Pada saat yang sama, membangun sistem manajemen keamanan energi elemental untuk mencegah kerusakan akibat kehilangan kendali energi.</li></ul><h3 id="c-mode-simbiosis-ras-konstruksi-mekanis" tabindex="-1">(C) Mode Simbiosis Ras Konstruksi Mekanis <a class="header-anchor" href="#c-mode-simbiosis-ras-konstruksi-mekanis" aria-label="Permalink to &quot;(C) Mode Simbiosis Ras Konstruksi Mekanis&quot;">​</a></h3><ul><li><strong>Ras Mesin</strong>: Memanfaatkan kemampuan komputasi dan pertahanan fisik Ras Mesin, memainkan peran inti dalam bidang konstruksi infrastruktur, produksi industri, perlindungan keamanan, dan eksplorasi ruang angkasa dalam. Ras Mesin adalah pembangun penting perangkat keras dan infrastruktur Jangkar.</li><li><strong>Ras Angka</strong>: Memanfaatkan kemampuan pemrosesan data dan manipulasi informasi Ras Angka, memainkan peran inti dalam bidang konstruksi informatisasi, analisis data, keamanan jaringan, dan kecerdasan buatan. Ras Angka adalah pemelihara penting teknologi komunikasi antar-dimensi dan jaringan simbiosis.</li><li><strong>Ras Kristal</strong>: Memanfaatkan kemampuan penyimpanan dan konversi energi Ras Kristal, memainkan peran dalam bidang cadangan energi, standardisasi energi, dan transmisi energi.</li></ul><h3 id="d-mode-simbiosis-ras-informasi-kesadaran" tabindex="-1">(D) Mode Simbiosis Ras Informasi Kesadaran <a class="header-anchor" href="#d-mode-simbiosis-ras-informasi-kesadaran" aria-label="Permalink to &quot;(D) Mode Simbiosis Ras Informasi Kesadaran&quot;">​</a></h3><ul><li><strong>Ras Mimpi</strong>: Memanfaatkan kemampuan komunikasi kesadaran Ras Mimpi, memainkan peran dalam bidang perawatan psikologis, penelitian kesadaran, komunikasi antar-ras, dan pertukaran budaya. Membangun sistem manajemen ruang mimpi untuk mencegah invasi kesadaran dan pelanggaran privasi.</li><li><strong>Ras Bayangan</strong>: Memanfaatkan kemampuan penyamaran dan pengintaian Ras Bayangan, memainkan peran dalam bidang pengintaian keamanan, pengumpulan intelijen, dan misi khusus. Pada saat yang sama, menetapkan norma perilaku Ras Bayangan, mencegah kemampuan tak terlihat digunakan untuk aktivitas ilegal.</li><li><strong>Ras Pikiran</strong>: Memanfaatkan kekuatan mental dan kemampuan manipulasi pikiran Ras Pikiran, memainkan peran dalam bidang penelitian evolusi kesadaran, perawatan mental, dan bimbingan kultivasi tingkat tinggi. Menetapkan norma penggunaan kekuatan mental, mencegah kontrol mental dan manipulasi kesadaran.</li></ul><h3 id="e-mode-simbiosis-ras-mutasi-campuran" tabindex="-1">(E) Mode Simbiosis Ras Mutasi Campuran <a class="header-anchor" href="#e-mode-simbiosis-ras-mutasi-campuran" aria-label="Permalink to &quot;(E) Mode Simbiosis Ras Mutasi Campuran&quot;">​</a></h3><p>Ras Mutasi Campuran, karena bentuk kehidupan khususnya, memerlukan kebijakan simbiosis yang lebih halus:</p><ul><li>Membangun sistem pendaftaran dan sertifikasi identitas Ras Mutasi Campuran, mengonfirmasi status hukumnya.</li><li>Menyediakan layanan publik yang disesuaikan, seperti kesehatan, pendidikan, dan perumahan, untuk berbagai bentuk campuran.</li><li>Menentang diskriminasi dan pengucilan terhadap Ras Mutasi Campuran, mempromosikan penerimaan sosial.</li><li>Untuk bentuk campuran khusus seperti Tubuh Jiwa Ganda, menerapkan 《58-Kriteria Etika Jiwa Ganda》 untuk manajemen khusus.</li></ul><h2 id="iv-perlindungan-budaya-ras-asing" tabindex="-1">IV. Perlindungan Budaya Ras Asing <a class="header-anchor" href="#iv-perlindungan-budaya-ras-asing" aria-label="Permalink to &quot;IV. Perlindungan Budaya Ras Asing&quot;">​</a></h2><p>Budaya ras asing adalah bagian penting dari keragaman budaya semua ras, dan Negara mengadopsi langkah-langkah berikut untuk melindunginya:</p><ol><li><strong>Sensus dan Pencatatan Budaya</strong>: Melakukan sensus dan pencatatan sistematis budaya setiap ras, membangun arsip budaya semua ras, mencegah hilangnya budaya.</li><li><strong>Perlindungan Bahasa dan Tulisan</strong>: Melindungi bahasa dan tulisan setiap ras, mendukung pengajaran dan penggunaan bahasa dan tulisan asing, membangun sistem layanan publik multibahasa.</li><li><strong>Perlindungan Festival Tradisional</strong>: Menghormati festival tradisional dan adat istiadat setiap ras, dan pengaturan hari libur publik mempertimbangkan festival penting setiap ras.</li><li><strong>Dukungan Pewarisan Budaya</strong>: Mendukung pelatihan pewaris budaya dan penyelenggaraan kegiatan budaya setiap ras, memberikan dukungan keuangan dan ruang.</li><li><strong>Promosi Pertukaran Budaya</strong>: Secara teratur menyelenggarakan festival budaya, pameran budaya, dan kegiatan lainnya dari semua ras, mempromosikan pertukaran dan saling belajar budaya.</li><li><strong>Perlindungan Hak Kekayaan Intelektual Budaya</strong>: Melindungi hak kekayaan intelektual budaya tradisional setiap ras, mencegah perampokan budaya dan komersialisasi yang tidak pantas.</li></ol><h2 id="v-tata-kelola-urusan-ras-asing" tabindex="-1">V. Tata Kelola Urusan Ras Asing <a class="header-anchor" href="#v-tata-kelola-urusan-ras-asing" aria-label="Permalink to &quot;V. Tata Kelola Urusan Ras Asing&quot;">​</a></h2><p>Negara mendirikan Departemen Urusan Semua Ras, khusus bertanggung jawab atas tata kelola dan koordinasi urusan ras asing:</p><ul><li><strong>Sistem Perwakilan Ras</strong>: Lembaga pemerintah di semua tingkatan dilengkapi dengan perwakilan ras asing secara proporsional, memastikan hak bicara ras asing.</li><li><strong>Kebijakan Adaptasi Ras</strong>: Merumuskan kebijakan layanan publik yang berbeda berdasarkan karakteristik fisiologis dan kebutuhan budaya ras yang berbeda.</li><li><strong>Mediasi Sengketa Ras</strong>: Membangun mekanisme mediasi sengketa ras, menyelesaikan kontradiksi dan konflik ras secara tepat waktu.</li><li><strong>Bantuan Hukum untuk Ras Asing</strong>: Memberikan bantuan hukum untuk ras asing, memastikan mereka menerima perlakuan yang sama dalam proses peradilan.</li><li><strong>Dukungan Pengembangan Ras Asing</strong>: Memberikan dukungan khusus untuk ras yang relatif tertinggal dalam pengembangan, membantu mereka meningkatkan tingkat peradaban dan standar hidup.</li></ul><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Ras asing bukanlah &quot;yang lain&quot; dari Ras Manusia, melainkan anggota yang setara dalam keluarga besar simbiosis semua ras. Peradaban Simbiosis Jangkar, melalui pembangunan sistem klasifikasi multidimensi, adopsi mode simbiosis yang berbeda, perlindungan budaya ras asing, dan peningkatan tata kelola urusan ras asing, memastikan bahwa setiap ras asing dapat menemukan posisi yang sesuai dalam sistem simbiosis, memanfaatkan keunggulan uniknya, dan berevolusi serta makmur bersama dengan ras lain.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>50-万族谱系总览 (Tinjauan Silsilah Semua Ras)</li><li>51-人族定位与特质 (Posisi dan Karakteristik Ras Manusia)</li><li>53-奇特生命识别标准 (Kriteria Identifikasi Kehidupan Aneh)</li><li>05-万族共进基本纲领 (Program Dasar Kemajuan Bersama Semua Ras)</li></ul>',39)])])}const b=n(r,[["render",t]]);export{o as __pageData,b as default};
